import{_ as a,o as t,c as s,ag as r}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"StaticAssetBundle — takoform_static_asset_bundle","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/static-asset-bundle.md","filePath":"proposals/edge/static-asset-bundle.md"}'),o={name:"proposals/edge/static-asset-bundle.md"};function i(n,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="staticassetbundle-—-takoform-static-asset-bundle" tabindex="-1">StaticAssetBundle — <code>takoform_static_asset_bundle</code> <a class="header-anchor" href="#staticassetbundle-—-takoform-static-asset-bundle" aria-label="Permalink to &quot;StaticAssetBundle — `takoform_static_asset_bundle`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An edge application serves immutable HTML, scripts, styles, images, and other files beside a Worker Version without turning those files into executable modules or provider state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>revision</code>. The whole desired state is one committed <code>manifestDigest</code>; a byte, path, media-type, or inventory change is a new revision.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The referenced artifact manifest has kind <code>StaticAssetBundle</code>, carries <code>files</code>, and carries no module members. The manifest fixes each relative path, media type, size, and blob digest. A host resolves and validates that exact manifest before storing the Form. File array order has no routing meaning.</p><p>A Worker Version refers to the bundle only through its optional closed <code>assets</code> object. Asset lookup order and SPA fallback are properties of that attachment, not of this bundle. The bundle grants no runtime binding and is not mutated when a version uses it (<a href="./../../spec/decisions/0033-edge-app-assets-and-sqlite-migrations-are-content-addressed.html">decision 0033</a>).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>The manifest is one immutable inventory with one content address. Splitting files into resources would replace one atomic revision with a partially updated set and make rollback unable to name the exact site bytes.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Mutable object storage, request routing rules, redirects, or generated content have independent lifecycle or behavior and do not belong in this revision.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>An uncommitted, foreign-tenant, wrong-kind, or invalid manifest fails before mutation. Deleting a bundle referenced by a Worker Version fails <code>dependency_in_use</code>. Raw file bytes never enter desired state or provider state; local authoring records only path, size, and digest evidence.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The immutable asset manifest served alongside an edge worker, separated from the executable module bundle so each content address has one meaning.</p>',20)])])}const p=a(o,[["render",i]]);export{m as __pageData,p as default};
